actions.script:
let filters = {}
try { filters = JSON.parse(filterJson || '{}') } catch (error) { filters = {} }
ec.context.putAll(Object.fromEntries(['state', 'systemMessageTypeId', 'systemMessageRemoteId', 'direction', 'reference', 'fromDate', 'thruDate', 'pageIndex']
    .map(name => [name, filters[name] == null ? null : String(filters[name])])))
let chosen = []
try { chosen = JSON.parse(targetsJson || '[]') } catch (error) { chosen = [] }
targetList = (Array.isArray(chosen) ? chosen : []).slice(0, 25).map(row => ({targetId: String(row?.targetId || ''), expectedRevision: String(row?.expectedRevision || '')}))

if.script:
const results = Array.from(done.resultList || [])
ec.message.addMessage((done.repeated ? 'Already done: ' : '') + done.appliedCount + ' of ' + results.length + ' done'
    + (done.refusedCount ? ', ' + done.refusedCount + ' not' : ''), done.refusedCount ? 'warning' : 'success')
for (const row of results.filter(found => !found.applied))
    ec.message.addMessage('Message ' + row.targetId + ': ' + (row.reason || 'not done'), 'warning')

service-call.in-map:
{state:(state || null), systemMessageTypeId:(systemMessageTypeId || null), systemMessageRemoteId:(systemMessageRemoteId || null),
                    direction:(direction || null), reference:(reference || null), fromDate:(fromDate || null), thruDate:(thruDate || null),
                    pageIndex:(pageIndex || 0), pageSize:50}

if.script:
const refusal = ec.message.hasError() ? ec.message.getErrorsString() : ''
ec.message.clearErrors()
reviewFailure = previewed?.previewList ? '' : (refusal || 'The messages could not be reviewed')
reviewAction = bulkActions.find(option => option.value === bulkAction) || null
reviewRows = reviewAction ? Array.from(previewed?.previewList || []).map(row => {
    const offered = Array.from(row.actionList || []).find(option => option.action === reviewAction.value) || {}
    return {targetId: row.targetId, stateText: row.stateText || '', ownerText: row.ownerApp || 'Not registered', eligible: offered.eligible === true,
        outcomeText: offered.eligible === true ? offered.consequence : (row.found ? offered.reason || 'Not offered' : 'No such message'),
        revision: row.revision}
}) : []
const allowed = reviewRows.filter(row => row.eligible)
reviewAllowedCount = allowed.length
// one key for this review: the same messages at the same revisions for the same action
let hash = 5381
for (const character of allowed.map(row => row.targetId + '@' + row.revision).join(',')) hash = ((hash * 33) ^ character.charCodeAt(0)) >>> 0
confirmValues = {action: reviewAction?.value, reason: bulkReason || null, filterJson: filterJson,
    targetsJson: JSON.stringify(allowed.map(row => ({targetId: row.targetId, expectedRevision: row.revision}))),
    operationKey: 'bulk.' + (reviewAction?.value || '') + '.' + allowed.length + '.' + hash.toString(16)}
